cat > /tmp/cs2.php <<'EOF'
<?php
$storage = new \Drupal\Core\Config\FileStorage(\Drupal::root() . '/../config/sync');
$names = $storage->listAll();
$active = \Drupal::configFactory()->listAll();
$onlysync = array_values(array_diff($names, $active));
echo "--- field.* only in sync ---\n";
foreach ($onlysync as $n) if (str_starts_with($n,'field.')) echo "$n\n";
echo "--- block.* only in sync (sample 40) ---\n";
$i=0; foreach ($onlysync as $n) if (str_starts_with($n,'block.')) { echo "$n\n"; if(++$i>=40) break; }
echo "--- views only in sync ---\n";
foreach ($onlysync as $n) if (str_starts_with($n,'views.')) echo "$n\n";
EOF
cd /workspace && cp /tmp/cs2.php /workspace/cs2_tmp.php && su ddevuser -c "ddev drush php:script cs2_tmp.php" 2>&1 | tail -90; rm -f /workspace/cs2_tmp.php
